// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(new Log()));
    }

    function testFuzz_property(uint256 dep, uint256 am, uint256 unlockExtra) public {
        vm.assume(dep <= VALUE_CAP);
        address actor = address(0xA11CE);
        uint256 minSum = c.MinSum();

        // admissible domain: deposit >= MinSum so the MinSum guard passes,
        // request exactly matches the deposit (the divergence case).
        dep = bound(dep, minSum, uint256(1) << 200);
        am = dep;

        vm.deal(actor, dep);
        vm.prank(actor);
        c.Put{value: dep}(0);

        // warp past the unlock time set by Put (which is now == block.timestamp)
        vm.warp(block.timestamp + 1 + (unlockExtra % 100));

        (uint256 unlockTime, uint256 balBefore) = c.Acc(actor);
        // keep the admissible domain: unlock time must have passed
        vm.assume(unlockTime < block.timestamp);
        vm.assume(balBefore >= minSum && balBefore == dep);

        uint256 cBalBefore = actor.balance;

        vm.prank(actor);
        try c.Collect(am) {} catch {}

        (uint256 unlockTime2, uint256 balAfter) = c.Acc(actor);
        unlockTime2; // silence unused warning

        // General rule: when the guard admits (balance >= am == balance), the
        // reference must debit exactly `am` and credit the caller with `am`.
        // The mutant's `> _am` guard refuses the exact-balance case, so neither
        // the debit nor the payout occurs.
        bool correct = balAfter == balBefore - am && actor.balance == cBalBefore + am;
        assertTrue(correct);
    }
}
